const fs=require('fs'),path=require('path'),{pathToFileURL}=require('url');const {chromium}=require('C:/Users/maco/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const out='dist/v010-extreme-runtime';
(async()=>{const browser=await chromium.launch({executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true,args:['--autoplay-policy=no-user-gesture-required']});const results=[];try{for(const name of ['jsnes-lite.readable.html','closure.min.html','jsnes-lite.min.html']){const p=await browser.newPage(),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>{window.__step=null;window.setTimeout=f=>{__step=f;return 1;};window.clearTimeout=()=>{__step=null;};});await p.goto(pathToFileURL(path.resolve(out,name)).href);const cases=[];for(const file of ['expected.nes','archives/lzma.7z','archives/lzma-header.7z','archives/lzma2.7z','archives/lzma2-header.7z','archives/properties-0-4-4.7z','archives/properties-4-0-0.7z','archives/properties-2-2-3.7z']){await p.locator('#rom').setInputFiles(out+'/tests/'+file);await p.waitForFunction(n=>document.getElementById('status').textContent===n&&!!window.__step,path.basename(file));const hash=await p.evaluate(()=>{for(let i=0;i<120;i++)__step();const data=document.querySelector('canvas').getContext('2d').getImageData(0,0,256,240).data;let h=2166136261;for(const x of data)h=Math.imul(h^x,16777619);return h>>>0;});cases.push({file,hash});if(hash!==cases[0].hash)throw Error('pixels differ');}for(const file of ['deflate.zip','comment.zip']){await p.locator('#rom').setInputFiles(out+'/tests/archives/'+file);await p.waitForFunction(()=>document.getElementById('status').textContent==='ROM'&&!window.__step);}results.push({name,errors,cases,zipRejected:true});console.log(JSON.stringify(results.at(-1)));await p.close();}}finally{await browser.close();fs.writeFileSync(out+'/verification-browser.json',JSON.stringify(results,null,2));}if(results.some(r=>r.errors.length))throw Error('page errors');})().catch(e=>{console.error(e);process.exitCode=1});
